tools.parametersSource:
{
    type: 'object',
    properties: {
      expression: {
        type: 'string',
        description: '要计算的数学表达式',
      },
    },
    required: ['expression'],
  }

{
    type: 'object',
    properties: {
      timezone: {
        type: 'string',
        description: 'IANA 时区名称，例如 "America/New_York"、"Asia/Shanghai"、"UTC"。默认值为 UTC',
        default: 'UTC',
      },
      format: {
        type: 'string',
        enum: ['iso', 'locale', 'unix'],
        description: '输出格式：iso（ISO 8601 格式）、locale（人类读取）、unix（时间戳）。默认值为 iso',
        default: 'iso',
      },
    },
    required: [],
  }

{
        type: 'object',
        properties: {
          confirmed: { type: 'boolean' },
          id: { type: 'string' },
          ...AGENT_CONFIG_PROPS,
        },
        required: ['confirmed', 'id'],
      }

{
        type: 'object',
        properties: {
          confirmed: { type: 'boolean' },
          id: { type: 'string' },
          agentName: { type: 'string' },
        },
        required: ['confirmed', 'id'],
      }

{
    type: 'object',
    properties: {
      question: { type: 'string' },
      options: {
        type: 'array',
        description: 'Must contain at least 2 meaningful, specific options. Do NOT use only a single "其他/Other" option.',
        minItems: 2,
        items: {
          type: 'object',
          properties: {
            label: { type: 'string' },
            description: { type: 'string' },
          },
          required: ['label'],
        },
      },
      multiSelect: { type: 'boolean' },
    },
    required: ['question', 'options'],
  }

{
    type: 'object',
    properties: {
      command: { type: 'string', description: '仅可执行文件名或路径，如 node、npm、C:\\Program Files\\nodejs\\node.exe；路径不要加引号，不要带参数。Windows 自动解析 PATH/PATHEXT 中的 .cmd/.bat。' },
      args: { type: 'array', items: { type: 'string' }, description: '逐项参数，保留原始内容，不手工包 shell 引号。例如 ["-v"] 或 ["-e", "console.log(\"hello\")"]。管道/重定向须显式使用对应 shell（Windows cmd.exe 的 args=["/d","/s","/c","完整 shell 脚本"]）；脚本内容由该 shell 解析。' },
      cwd: { type: 'string', description: '工作目录，仍受当前工作区安全策略限制' },
      timeoutMs: { type: 'number', description: '可选超时毫秒数；省略时所有模式持续运行直到退出或取消' },
      background: { type: 'boolean', description: '默认false；true在成功启动后立即返回jobId，后续读取输出或取消' },
    }, required: ['command'],
  }

{
    type: 'object',
    properties: {
      action: {
        type: 'string',
        enum: ['status', 'search', 'callers', 'callees', 'impact', 'files', 'index'],
        description:
          'status=索引统计/建索引进度；search=按关键词搜符号；callers=谁调用了它；callees=它调用了谁；' +
          'impact=改动影响面；files=索引内文件清单；index=为当前工作区创建索引（仅当用户明确要求时调用）',
      },
      query: {
        type: 'string',
        description: '符号名或关键词（search 必填；callers/callees/impact 不传 nodeId 时必填）',
      },
      nodeId: {
        type: 'string',
        description: '可选：图节点 ID（形如 function:xxxx），已知时可直接传入跳过搜索',
      },
      path: {
        type: 'string',
        description: '项目根目录（相对工作区或绝对路径），默认当前工作区',
      },
      limit: { type: 'number', description: '返回条数上限，默认 20' },
      depth: { type: 'number', description: 'impact 的最大调用链深度，默认 3' },
    },
    required: ['action'],
  }

{
    type: 'object',
    properties: {
      path: { type: 'string' },
      recursive: { type: 'boolean' },
      maxResults: { type: 'integer', minimum: 1, maximum: 2000, description: '本次所有工作区合计的最大条目数，默认500' },
    },
    required: [],
  }

{
    type: 'object', additionalProperties: false,
    properties: {
      path: { type: 'string', minLength: 1, description: '目标文件路径，使用同一文件最近一次 read_file / write_file / edit_file 返回的 path。' },
      expectedHash: { type: 'string', pattern: '^sha256:[a-f0-9]{64}$', description: '同一文件最近一次 read_file / write_file / edit_file 成功返回的完整文件字节 SHA-256 版本；不是片段 hash，不要自行猜测。' },
      edits: { type: 'array', minItems: 1, description: '在同一原文件上同时定位；不使用前一个替换产生的内容定位后一个。', items: {
        type: 'object', additionalProperties: false,
        properties: {
          oldText: { type: 'string', minLength: 1, description: '无行号的精确原文。必须在原文件中仅出现一次，换行和空白也必须相同。' },
          newText: { type: 'string', description: '替换后的原文，可为空以删除该片段；需要保留的 CRLF/BOM 请原样保留。' },
        }, required: ['oldText', 'newText'],
      } },
    }, required: ['path', 'expectedHash', 'edits'],
  }

{
    type: 'object',
    properties: {
      path: { type: 'string', description: '确切文件路径；相对路径基于当前工作区解析，不按文件名猜测其他目录。' },
      start_line: { type: 'number', description: '起始行号（从 1 开始），默认 1' },
      end_line: { type: 'number', description: '结束行号，默认读取 300 行' },
      mode: { type: 'string', enum: ['auto', 'full', 'summary', 'vision', 'ocr', 'exact'], description: 'auto(默认), full(全文), summary(摘要/签名), vision(图片预览), ocr(文本提取), exact(原始UTF-8 JSON，含完整expectedHash，可按行分页)' },
    },
    required: ['path'],
  }

{
    type: 'object',
    properties: {
      includeTools: { type: 'boolean', description: '是否包含工具列表，默认 true' },
      includeHistory: { type: 'boolean', description: '是否包含对话历史，默认 false' }
    },
    required: []
  }

{ type: 'object', additionalProperties: false, properties: {
    query: { type: 'string', description: '原文关键词，按字面匹配，非正则' },
    messageId: { type: 'string', description: '读取检索结果中的准确消息ID' },
    role: { type: 'string', enum: ['user', 'assistant', 'tool', 'system'] },
    offset: { type: 'integer', minimum: 0 },
    limit: { type: 'integer', minimum: 1, maximum: 10 },
    contentOffset: { type: 'integer', minimum: 0, description: '读取长消息原文的字符起点' },
    imageIndex: { type: 'integer', minimum: 0, description: '结合messageId取回该消息images中的原图，索引从0开始' },
  } }

{
    type: 'object',
    properties: {
      url: { type: 'string' },
      method: { type: 'string', enum: ['GET', 'POST', 'PUT', 'DELETE', 'PATCH'] },
      headers: { type: 'object' },
      body: { type: 'string', description: '请求体' },
      timeout: { type: 'integer', minimum: 0, description: '可选超时ms；省略或 0 表示直到完成或取消' },
      auth: {
        type: 'object',
        description: '认证: {type:"bearer",token:"xxx"} 或 {type:"basic",username,password} 或 {type:"apikey",apiKey,apiKeyHeader,apiKeyPrefix}',
      },
      followRedirects: { type: 'boolean' },
      responseType: { type: 'string', enum: ['auto', 'json', 'text'] }
    },
    required: ['url']
  }

{
    type: 'object',
    properties: {
      packageName: { type: 'string', description: '包名，如 lodash 或 lodash@4.17.21' },
      version: { type: 'string' },
      global: { type: 'boolean' },
      saveDev: { type: 'boolean', description: '--save-dev' },
      installPath: { type: 'string' },
      timeoutMs: { type: 'integer', minimum: 0, description: '可选安装超时毫秒数；省略或 0 表示直到完成或取消' },
      confirm: { type: 'boolean', description: '确认后设为 true 执行' }
    },
    required: ['packageName']
  }

{
    type: 'object',
    properties: {
      path: {
        type: 'string',
        description: '工作区路径，默认为当前工作区目录'
      },
      global: {
        type: 'boolean',
        description: '是否列出全局安装的包，默认 false'
      }
    },
    required: []
  }

{
    type: 'object',
    properties: {
      filePath: { type: 'string', description: '支持的 TypeScript/JavaScript 文件路径（相对 workspace 或绝对路径）；不支持 .html/.css。' },
      content: { type: 'string', description: '可选：未保存的文件内容，传入则优先使用' },
      adapters: { type: 'array', items: { type: 'string', enum: ['typescript', 'eslint'] }, description: '指定适配器；不传时运行支持当前后缀且可用的适配器。ESLint 需要项目配置；指定但不可用时返回 unsupported。' },
    },
    required: ['filePath'],
  }

{
      type: 'object',
      properties: {
        content: { type: 'string', description: '记忆的内容，使用简洁完整的陈述句' },
        type: { type: 'string', enum: ['fact', 'preference', 'decision', 'lesson', 'narrative', 'milestone'], description: '记忆类型' },
        tags: { type: 'array', items: { type: 'string' }, description: '3-5个分类标签' },
        emotionalValence: { type: 'number', description: '情感效价 (-1.0 到 1.0)' },
        emotionalTrigger: { type: 'string', description: '触发情绪的事物或情境' },
      },
      required: ['content', 'type', 'tags'],
    }

{
      type: 'object',
      properties: { tags: { type: 'array', items: { type: 'string' }, description: '用于检索的标签列表' } },
      required: ['tags'],
    }

{
      type: 'object',
      properties: {
        sourceId: { type: 'string' },
        targetId: { type: 'string' },
        type: { type: 'string', enum: ['reinforces', 'contradicts', 'leads_to', 'part_of', 'similar_to', 'tagged_with'] },
        description: { type: 'string' },
        strength: { type: 'number', default: 0.5 },
      },
      required: ['sourceId', 'targetId', 'type', 'description'],
    }

{
    type: 'object', additionalProperties: false,
    properties: {
      operation: { type: 'string', enum: ['inspect', 'create', 'edit', 'append_sheets', 'recalculate'] },
      path: { type: 'string', minLength: 1, maxLength: 4096, description: '当前工作区中的 .docx/.xlsx/.pptx/.pdf 目标路径。PDF支持create/inspect，其他格式也支持定点edit；recalculate只支持xlsx。' },
      expectedHash: { type: 'string', pattern: '^(missing|sha256:[a-f0-9]{64})$', description: 'create 必须为 missing；edit/append_sheets/recalculate 必须复用同文件最近一次工具返回的 sha256；inspect 首次可省略，contentOffset>0时必须传同文件上一页的 sha256，防止混读不同版本。' },
      contentOffset: { type: 'integer', minimum: 0, maximum: maxContentOffset, description: '仅 inspect：使用上页 contentPage.nextOffset（UTF-16字符位置）；只分页检查预览，不代表完整文档。' },
      contentLimit: { type: 'integer', minimum: 2, maximum: 32000, description: '仅 inspect：本页预览字符上限，实际会按工具输出预算进一步缩短。' },
      markdown: { type: 'string', minLength: 1, maxLength: 300000, description: 'Word/PDF create 使用，支持标题、正文、列表、表格。PDF由Aether直接排版，并非从Word/PPT转换。' },
      title: { type: 'string', maxLength: 256, description: '可选的独立可见标题，同时写入文档属性；避免与 Markdown 首标题重复。' }, author: { type: 'string', maxLength: 200 },
      presentation: { type: 'object', additionalProperties: false, description: '仅PPTX create：分页的演示内容，过长内容拆成多页，不缩成不可读小字。', properties: {
        slides: { type: 'array', minItems: 1, maxItems: 40, items: { type: 'object', additionalProperties: false, properties: {
          title: { type: 'string', minLength: 1, maxLength: 100, description: '单行短标题，最多94个英文字符宽度（中文约47字）。' },
          bullets: { type: 'array', maxItems: 6, description: '每页最多6条，含表格时最多2条；每条不换行，最多140英文字符宽度（中文约70字）。', items: { type: 'string', minLength: 1, maxLength: 160 } },
          table: { type: 'object', additionalProperties: false, description: '最多6列、8行；同页有要点时最多5行。单元格不换行，英文字符宽度最多100/列数，中文按2计；长内容拆页。', properties: {
            headers: { type: 'array', minItems: 1, maxItems: 6, items: { type: 'string', minLength: 1, maxLength: 100 } },
            rows: { type: 'array', maxItems: 8, items: { type: 'array', minItems: 1, maxItems: 6, items: { anyOf: [{ type: 'string', maxLength: 100 }, { type: 'number' }] } } },
          }, required: ['headers', 'rows'] },
          notes: { type: 'string', maxLength: 3000 },
        }, required: ['title'] } },
      }, required: ['slides'] },
      workbook: { type: 'object', additionalProperties: false, description: 'Excel create 或 append_sheets 的新增表内容。append_sheets 每次最多4张（建议一张），不重复提交已存在的表。', properties: { sheets: { type: 'array', minItems: 1, maxItems: 12,
        items: { type: 'object', additionalProperties: false, properties: {
          name: { type: 'string', minLength: 1, maxLength: 31 },
          columns: { type: 'array', minItems: 1, maxItems: 100, items: { type: 'object', additionalProperties: false, properties: {
            header: { type: 'string', minLength: 1, maxLength: 255 }, key: { type: 'string', minLength: 1, maxLength: 128 },
            type: { type: 'string', enum: ['text', 'number', 'date', 'percent'] }, width: { type: 'number', minimum: 8, maximum: 80 },
          }, required: ['header', 'key'] } },
          rows: { type: 'array', maxItems: 10000, items: { type: 'object', additionalProperties: { anyOf: [
            { type: 'string', maxLength: 32000 }, { type: 'number' }, { type: 'boolean' }, { type: 'null' },
            { type: 'object', additionalProperties: false, properties: { formula: { type: 'string', minLength: 1, maxLength: 2000 } }, required: ['formula'] },
          ] } } },
        }, required: ['name', 'columns', 'rows'] } } }, required: ['sheets'] },
      edits: { type: 'array', minItems: 1, maxItems: 1000, items: { anyOf: [
        { type: 'object', additionalProperties: false, properties: { oldText: { type: 'string', minLength: 1, maxLength: 32000 }, newText: { type: 'string', maxLength: 32000 } }, required: ['oldText', 'newText'] },
        { type: 'object', additionalProperties: false, description: '仅 PPTX：复用 inspect 返回的 slide/textRun 定位，oldText 必须在该普通文本节点内唯一；字段不可编辑。省略定位时仍要求全稿唯一。', properties: {
          oldText: { type: 'string', minLength: 1, maxLength: 10000 }, newText: { type: 'string', maxLength: 10000 },
          slide: { type: 'integer', minimum: 1, maximum: 40, description: '幻灯片显示顺序，从 1 开始，与 ZIP 文件名顺序无关。' },
          textRun: { type: 'integer', minimum: 1, maximum: 100000, description: '该页 inspect 标记的文本节点编号，从 1 开始，需 editable=true。' },
        }, required: ['oldText', 'newText', 'slide', 'textRun'] },
        { type: 'object', additionalProperties: false, properties: { sheet: { type: 'string', minLength: 1, maxLength: 31 }, cell: { type: 'string', pattern: '^[A-Z]{1,3}[1-9][0-9]{0,6}$' }, value: { anyOf: [
          { type: 'string', maxLength: 32000 }, { type: 'number' }, { type: 'boolean' }, { type: 'null' },
          { type: 'object', additionalProperties: false, properties: { formula: { type: 'string', minLength: 1, maxLength: 2000 } }, required: ['formula'] },
        ] } }, required: ['sheet', 'cell', 'value'] },
      ] } },
    }, required: ['operation', 'path'],
  }

{
    type: 'object', additionalProperties: false,
    properties: {
      path: { type: 'string', minLength: 1, maxLength: 4096, description: '当前工作区中的 .docx/.xlsx/.pptx/.pdf 文件路径。' },
      expectedHash: { type: 'string', pattern: '^sha256:[a-f0-9]{64}$', description: '首次可省略；分页时必须复用同文件上一页返回的 sha256，防止混读不同版本。' },
      contentOffset: { type: 'integer', minimum: 0, maximum: maxContentOffset, description: '上页 contentPage.nextOffset（UTF-16字符位置），仅覆盖已提取预览。' },
      contentLimit: { type: 'integer', minimum: 2, maximum: 32000, description: '本页预览字符上限，仍受工具输出预算限制。' },
    }, required: ['path'],
  }

{
    type: 'object',
    properties: {
      pattern: { type: 'string' },
      cwd: { type: 'string' },
      limit: { type: 'number' },
      offset: { type: 'number', description: '跳过前 offset 个结果，用于继续分页' },
    },
    required: ['pattern'],
  }

{
      type: 'object',
      properties: {
        name: {
          type: 'string',
          description: '想要查看的技能名称（须与 list_skills 中列出的名称一致）',
        },
        resource: {
          type: 'string', minLength: 1, maxLength: 1024,
          description: '可选：所选技能中按需读取的 references/*.md 相对路径；不传时返回原 SKILL.md 正文。',
        },
      },
      required: ['name'],
    }

{
    type: 'object',
    properties: {
      command: {
        type: 'string',
        description:
          '要执行的完整 Shell 命令，必须与 SKILL.md 中展示的格式完全一致。' +
          '示例：`bash "$SKILLS_ROOT/web-search/scripts/search.sh" "TypeScript 5 features" 10`',
      },
      timeoutMs: {
        type: 'integer', minimum: 0, maximum: MAX_OPERATION_TIMEOUT_MS,
        description: '可选执行超时时间（毫秒；省略或 0 表示不限时）。用户停止会话时仍会取消脚本。',
      },
    },
    required: ['command'],
  }

{
      type: 'object',
      properties: {
        status: { type: 'string', enum: ['pending','running','done','failed','cancelled'] },
        limit: { type: 'number' },
      },
      required: [],
    }

{
    type: 'object', additionalProperties: false,
    properties: {
      plan: {
        type: 'array', maxItems: 100,
        items: {
          type: 'object', additionalProperties: false,
          properties: {
            id: { type: 'string', minLength: 1, maxLength: 128 },
            step: { type: 'string', minLength: 1, maxLength: 240 },
            status: { type: 'string', enum: ['pending', 'in_progress', 'completed', 'cancelled'] },
          }, required: ['step', 'status'],
        },
      },
      explanation: { type: 'string', maxLength: 4000, description: '可选的计划变化说明；不要重复普通对话正文。' },
    }, required: ['plan'],
  }

{ type: 'object', properties: {
      title: { type: 'string' }, description: { type: 'string' }, priority: { type: 'string', enum: ['low', 'medium', 'high'] },
      dueAt: { type: 'string', description: 'ISO 8601' },
    }, required: ['title'] }

{ type: 'object', properties: {
      id: { type: 'string' }, title: { type: 'string' }, description: { type: 'string' },
      status: { type: 'string', enum: ['pending', 'in_progress', 'done', 'cancelled'] },
      priority: { type: 'string', enum: ['low', 'medium', 'high'] }, dueAt: { type: 'string' },
    }, required: ['id'] }

{
    type: 'object',
    properties: {
      url: { type: 'string' },
      convertToMarkdown: { type: 'boolean' },
    },
    required: ['url']
  }
